import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<() => Promise<string>>().mockResolvedValue('success');

      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
            required: ['location'],
          },
        },
        execute
      );

      const response = await registry.execute('test-tool', {});
      const mockState = execute.mock;

      expect({calls: mockState.calls.length, result: response.result}).toEqual({
        calls: 0,
        result: expect.stringContaining("must have required property 'location'"),
      });
    });

    it('passes valid input with an unlisted extra property through to the executor unchanged exactly once', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<() => Promise<string>>().mockResolvedValue('success');

      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
            required: ['location'],
          },
        },
        execute
      );

      const input = {location: 'Paris', extra: 'data'};
      await registry.execute('test-tool', input);

      expect(execute).toHaveBeenCalledTimes(1);
      expect(execute.mock.calls[0]?.[0]).toEqual(input);
    });
  });
});
