    it('asserts a function-valued tool definition whose returned schema differs between calls is validated against the schema current at that call, not a stale cached one', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<() => Promise<string>>().mockResolvedValue('success');

      let callCount = 0;
      registry.register(
        () => {
          callCount++;
          return {
            name: 'dynamic-tool',
            description: 'A dynamic tool',
            inputSchema: {
              type: 'object',
              properties: {
                flag: { type: callCount === 1 ? 'string' : 'number' }
              }
            }
          };
        },
        execute
      );

      // First call requires flag as string
      let response = await registry.execute('dynamic-tool', {flag: 'value'});
      expect(execute).toHaveBeenCalledTimes(1);
      expect(response).toEqual({result: 'success'});

      // Second call requires flag as number
      response = await registry.execute('dynamic-tool', {flag: 42});
      expect(execute).toHaveBeenCalledTimes(2);
      expect(response).toEqual({result: 'success'});

      // Third call should fail if string is passed
      response = await registry.execute('dynamic-tool', {flag: 'value'});
      expect(execute).toHaveBeenCalledTimes(2);
      expect(response.result).toContain('must be number');
    });
