const newTest = `
  it('drives a stub provider through a rejected tool call followed by a corrected retry without rejecting', async () => {
    let callCount = 0;
    const provider: AIProvider = {
      async *sendMessage(params) {
        callCount++;
        if (callCount === 1) {
          yield {type: 'tool_use', toolCall: {id: 'c1', name: 'my_tool', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }

        // Assert the rejection was passed back
        const lastMessage = params.messages[params.messages.length - 1];
        expect(lastMessage?.role).toBe('user');
        if (lastMessage?.role === 'user' && typeof lastMessage.content !== 'string') {
          const content = lastMessage.content[0];
          if (content && 'type' in content && content.type === 'tool_result') {
            expect(content.content).toContain('required property');
          }
        }

        yield {type: 'text', text: 'Ok, I fixed it'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured() { return {} as any; }
    };

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'my_tool',
        description: 'a tool',
        inputSchema: {
          type: 'object',
          properties: { requiredField: { type: 'string' } },
          required: ['requiredField'],
        }
      },
      async () => 'success'
    );

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('hi'));
    expect(result).toBe('Ok, I fixed it');
    expect(callCount).toBe(2);
  });
`;

code = code.replace(/it\('stops after one round when nothing asked for a tool',/, newTest + "\n  it('stops after one round when nothing asked for a tool',");
fs.writeFileSync(path, code);
